TABLE_NAME = "geo_countries"

def get_client(endpoint: str):
    return boto3.client(
        "dynamodb",
        endpoint_url=endpoint,
        region_name="us-east-1",
        config=LOCAL_CONFIG,
    )

def ensure_table(client):
    try:
        client.create_table(
            TableName=TABLE_NAME,
            KeySchema=[{"AttributeName": "cca2", "KeyType": "HASH"}],
            AttributeDefinitions=[{"AttributeName": "cca2", "AttributeType": "S"}],
            BillingMode="PAY_PER_REQUEST",
        )
        client.get_waiter("table_exists").wait(TableName=TABLE_NAME)
        print(f"Created table {TABLE_NAME}")
    except ClientError as e:
        if e.response["Error"]["Code"] == "ResourceInUseException":
            print(f"Table {TABLE_NAME} already exists")
        else:
            raise

def seed(client):
    written = 0
    for batch_start in range(0, len(COUNTRIES), 25):
        batch = COUNTRIES[batch_start:batch_start + 25]
        requests = []
        for c in batch:
            item = {
                "cca2":         {"S": c["cca2"]},
                "cca3":         {"S": c["cca3"]},
                "name_common":  {"S": c["name_common"]},
                "name_official":{"S": c["name_official"]},
                "region":       {"S": c["region"]},
                "subregion":    {"S": c["subregion"]},
            }
            if c["ccn3"]:
                item["ccn3"] = {"S": c["ccn3"]}
            requests.append({"PutRequest": {"Item": item}})
        client.batch_write_item(RequestItems={TABLE_NAME: requests})
        written += len(batch)
    print(f"Seeded {written} countries into {TABLE_NAME}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--endpoint", default="http://localhost:4570")
    args = parser.parse_args()

    client = get_client(args.endpoint)
    ensure_table(client)
    seed(client)

if __name__ == "__main__":
    main()
